static inline const Properties *qGetProp(ushort ucs2) {
    int index = GET_PROP_INDEX_UCS2(ucs2);
    return uc_properties + index;
}

#define MAX_BUFF_SIZE (long)1024*1024
/* Block sizes */
#define HEADER_SIZE			768
#define BIG_BLOCK_SIZE			512
#define PROPERTY_SET_STORAGE_SIZE	128
#define SMALL_BLOCK_SIZE		 64
/*
 * 解析 OLE 时会把 FAT/depot 表一次性读到内存。攻击者可以伪造文件大小或
 * depot 长度，让这里尝试申请很大的内存，所以需要设置一个上限。
 *
 * 这个上限可能会拒绝极少数“格式合法但特别大”的旧版 OLE 文件。若以后必须
 * 支持这类文件，正确做法是把 FAT/depot 改成按需读取或分块读取；不要只是
 * 调大这个值，否则会重新引入内存耗尽风险。
 */
static const size_t MAX_OLE_DEPOT_ALLOCATION_BYTES = 64u * 1024u * 1024u;

/* PPT Data*/
#define PPT_RECORD_HEADER 8
#define PPT_TEXT_CHARS_ATOM 0x0FA0
#define PPT_TEXT_BYTES_ATOM 0x0FA8
#define PPT_SLIDE_MASTER 0x03F8
#define PPT_SLIDE 0x03EE
// MS-PPT 未规定容器的最大嵌套层数；这里设置实现侧上限，
// 避免畸形文件构造超深容器树耗尽调用栈。64 是保守的安全值，并非规范值。
// TODO: 后续将递归解析改为显式容器栈，再移除这个人为嵌套深度限制。
static const size_t MAX_PPT_RECORD_RECURSION_DEPTH = 64;
// ULONG 的最大值不可能是有效的下一条记录位置，用作统一的解析失败标记。
static const ULONG PPT_RECORD_ERROR = static_cast<ULONG>(-1);

/* Special block numbers */
#define END_OF_CHAIN			0xfffffffeUL
#define UNUSED_BLOCK			0xffffffffUL

/* Switch size of Depot use */
#define MIN_SIZE_FOR_BBD_USE		0x1000

#define STREQ(x,y)	(*(x) == *(y) && strcmp(x,y) == 0)
#define STRNEQ(x,y,n)	(*(x) == *(y) && strncmp(x,y,n) == 0)

#define BIT(x)		(1UL << (x))

static ULONG	*aulSmallBlockList = NULL;
static size_t	tSmallBlockListLen = 0;
static UCHAR	**ppAnchor = NULL;
static size_t	tNextFree = 0;
static size_t	tMaxElements = 0;
#define ELEMENTS_TO_ADD	30

// 判断 [tOffset, tOffset + tLength) 是否完全落在缓冲区内。
// 使用减法形式，避免直接计算 tOffset + tLength 时发生整数回绕。
static bool bRangeWithinBuffer(size_t tOffset, size_t tLength, size_t tBufferLength) {
    return tOffset <= tBufferLength && tLength <= tBufferLength - tOffset;
}

/* Show that a PPS number or index should not be used */
#define PPS_NUMBER_INVALID	0xffffffffUL

/* Macros */
/* Get macros */
#define ucGetByte(i,a)		((unsigned char)(a[i]))
#define usGetWord(i,a)		((unsigned short)\
					((unsigned int)(a[(i)+1])<<8|\
					 (unsigned int)(a[i])))
#define ulGetLong(i,a)		((unsigned long)(a[i])|\
					(unsigned long)(a[(i)+1])<<8|\
					(unsigned long)(a[(i)+2])<<16|\
					(unsigned long)(a[(i)+3])<<24)
#define usGetWordBE(i,a)	((unsigned short)\
					((unsigned int)(a[i])<<8|\
					 (unsigned int)(a[(i)+1])))
#define ulGetLongBE(i,a)	((unsigned long)(a[(i)+3])|\
					(unsigned long)(a[(i)+2])<<8|\
					(unsigned long)(a[(i)+1])<<16|\
					(unsigned long)(a[i])<<24)

void* xmalloc(size_t tSize) {
    void	*pvTmp;

    if(tSize == 0) {
        tSize = 1;
    }
    pvTmp = malloc(tSize);
    if(pvTmp == NULL) {
        return NULL;
    }
    return pvTmp;
} /* end of xmalloc */

void* xcalloc(size_t tNmemb, size_t tSize) {
    void	*pvTmp;

    if(tNmemb == 0 || tSize == 0) {
        tNmemb = 1;
        tSize = 1;
    }
    /* 防止 32 位平台或畸形输入下 nmemb * size 发生回绕。 */
    if(tNmemb > std::numeric_limits<size_t>::max() / tSize) {
        return NULL;
    }
    pvTmp = calloc(tNmemb, tSize);
    if(pvTmp == NULL) {
        return NULL;
    }
    return pvTmp;
} /* end of xcalloc */

static bool bOleAllocationWithinBudget(size_t tNmemb, size_t tSize) {
    if(tNmemb == 0 || tSize == 0) {
        return true;
    }
    if(tNmemb > std::numeric_limits<size_t>::max() / tSize) {
        return false;
    }
    return tNmemb * tSize <= MAX_OLE_DEPOT_ALLOCATION_BYTES;
}

void* xrealloc(void *pvArg, size_t tSize) {
    void	*pvTmp;

    pvTmp = realloc(pvArg, tSize);
    return pvTmp;
} /* end of xrealloc */


void* xfree(void *pvArg) {
    if(pvArg != NULL) {
        free(pvArg);
    }
    return NULL;
} /* end of xfree */

bool bReadBytes(unsigned char *aucBytes, size_t tMemb, long lOffset, FILE *pFile) {
//    printf("[%s]-[%d] wana read [%d] offset[%d]\n",__FUNCTION__,__LINE__,tMemb, lOffset);

    if(fseek(pFile, lOffset, SEEK_SET) != 0) {
        return false;
    }
    if(fread(aucBytes, sizeof(unsigned char), tMemb, pFile) != tMemb) {
        return false;
    }
    return true;
} /* end of bReadBytes */

#define SIZE_RATIO	(BIG_BLOCK_SIZE/SMALL_BLOCK_SIZE)

ULONG ulDepotOffset(ULONG ulIndex, size_t tBlockSize) {
    ULONG	ulTmp;
    size_t	tTmp;

    switch(tBlockSize) {
    case BIG_BLOCK_SIZE:
        return (ulIndex + 1) * BIG_BLOCK_SIZE;
    case SMALL_BLOCK_SIZE:
        tTmp = (size_t)(ulIndex / SIZE_RATIO);
        ulTmp = ulIndex % SIZE_RATIO;
        if(aulSmallBlockList == NULL ||
                tTmp >= tSmallBlockListLen) {
            return 0;
        }
        return ((aulSmallBlockList[tTmp] + 1) * SIZE_RATIO +
                ulTmp) * SMALL_BLOCK_SIZE;
    default:
        return 0;
    }
} /* end of ulDepotOffset */

bool bReadBuffer(FILE *pFile, ULONG ulStartBlock,
                 const ULONG *aulBlockDepot, size_t tBlockDepotLen, size_t tBlockSize,
                 UCHAR *aucBuffer, ULONG ulOffset, size_t tToRead) {
    ULONG	ulBegin, ulIndex;
    size_t	tLen;

    for(ulIndex = ulStartBlock;ulIndex != END_OF_CHAIN && tToRead != 0;ulIndex = aulBlockDepot[ulIndex]) {
        if(ulIndex >= (ULONG)tBlockDepotLen) {
            if(tBlockSize >= BIG_BLOCK_SIZE) {
                qWarning() << "The Big Block Depot is damaged";
            } else {
                qWarning() << "The Small Block Depot is damaged";
            }
            return (tToRead == 0);
        }
        if(ulOffset >= (ULONG)tBlockSize) {
            ulOffset -= tBlockSize;
            continue;
        }
        ulBegin = ulDepotOffset(ulIndex, tBlockSize) + ulOffset;
        tLen = min(tBlockSize - (size_t)ulOffset, tToRead);
        ulOffset = 0;
        if(!bReadBytes(aucBuffer, tLen, ulBegin, pFile)) {
            return false;
        }
        aucBuffer += tLen;
        tToRead -= tLen;
    }
    return (tToRead == 0);
} /* end of bReadBuffer */

static ULONG ulReadLong(FILE *pFile, ULONG ulOffset) {
    UCHAR	aucBytes[4];

    if(!bReadBytes(aucBytes, 4, ulOffset, pFile)) {
        return ULONG_MAX;
    }
    return ulGetLong(0, aucBytes);
} /* end of ulReadLong */

static size_t tReadBlockIndices(FILE *pFile, ULONG *aulBlockDepot,
                                size_t tMaxRec, ULONG ulOffset) {
    size_t	tDone;
    int	iIndex;
    UCHAR	aucBytes[BIG_BLOCK_SIZE];

    /* Read a big block with BBD or SBD indices */
    if(!bReadBytes(aucBytes, BIG_BLOCK_SIZE, ulOffset, pFile)) {
        return 0;
    }
    /* Split the big block into indices, an index is four bytes */
    tDone = min(tMaxRec, (size_t)BIG_BLOCK_SIZE / 4);
    for(iIndex = 0; iIndex < (int)tDone; iIndex++) {
        aulBlockDepot[iIndex] = ulGetLong(4 * iIndex, aucBytes);
    }
    return tDone;
} /* end of tReadBlockIndices */

static bool bGetSBD(FILE *pFile, const ULONG *aulDepot, size_t tDepotLen,
                    ULONG *aulSBD, size_t tSBDLen) {
    ULONG	ulBegin;
    size_t	tToGo, tDone;
    int	iIndex;

    tToGo = tSBDLen;
    for(iIndex = 0; iIndex < (int)tDepotLen && tToGo != 0; iIndex++) {
        ulBegin = (aulDepot[iIndex] + 1) * BIG_BLOCK_SIZE;
        tDone = tReadBlockIndices(pFile, aulSBD, tToGo, ulBegin);
        if(tDone == 0) {
            return false;
        }
        aulSBD += tDone;
        tToGo -= tDone;
    }
    return tToGo == 0;
} /* end of bGetSBD */

static void vName2String(char *szName, const UCHAR *aucBytes, size_t tNameSize) {
    char	*pcChar;
    size_t	tIndex;

    if(tNameSize < 2) {
        szName[0] = '\0';
        return;
    }
    for(tIndex = 0, pcChar = szName; tIndex < 2 * tNameSize; tIndex += 2, pcChar++) {
        *pcChar = (char)aucBytes[tIndex];
    }
    szName[tNameSize - 1] = '\0';
} /* end of vName2String */


bool vAdd2PropModList(const UCHAR *aucPropMod, size_t tAvailable) {
    size_t	tLen;

    // 属性修改块前两个字节记录后续数据长度，因此完整复制长度还要加上头部的 2 字节。
    // 必须在读取长度和 memcpy 前确认源缓冲区确实包含这些数据。
    if(aucPropMod == NULL || tAvailable < 2) {
        return false;
    }

    tLen = 2 + (size_t)usGetWord(0, aucPropMod);
    if(tLen > tAvailable) {
        return false;
    }

    if(tNextFree >= tMaxElements) {
        // 先计算并申请新容量；只有 realloc 成功后才更新全局容量。
        // 否则一次扩容失败会让后续调用误认为数组已经变大，造成越界写入。
        if(tMaxElements > std::numeric_limits<size_t>::max() - ELEMENTS_TO_ADD) {
            return false;
        }
        const size_t tNewMaxElements = tMaxElements + ELEMENTS_TO_ADD;
        if(tNewMaxElements > std::numeric_limits<size_t>::max() / sizeof(UCHAR *)) {
            return false;
        }
        void *pvTmp = realloc(ppAnchor, tNewMaxElements * sizeof(UCHAR *));
        if(pvTmp == NULL) {
            return false;
        }
        ppAnchor = static_cast<UCHAR **>(pvTmp);
        tMaxElements = tNewMaxElements;
    }

    ppAnchor[tNextFree] = (UCHAR*)xmalloc(tLen);
    if(ppAnchor[tNextFree] == NULL) {
        return false;
    }
    memcpy(ppAnchor[tNextFree], aucPropMod, tLen);
    tNextFree++;
    return true;
} /* end of vAdd2PropModList */

static void vComputePPSlevels(ppsEntryType *atPPSlist, ppsEntryType *pNode,
                              int iLevel, int iRecursionLevel) {
    if(iRecursionLevel > 25) {
        /* This removes the possibility of an infinite recursion */
        return;
    }
    if(pNode->iLevel <= iLevel) {
        /* Avoid entering a loop */
        return;
    }

    pNode->iLevel = iLevel;

    if(pNode->ulDir != PPS_NUMBER_INVALID) {
        vComputePPSlevels(atPPSlist,
                          &atPPSlist[pNode->ulDir],
                          iLevel + 1,
                          iRecursionLevel + 1);
    }
    if(pNode->ulNext != PPS_NUMBER_INVALID) {
        vComputePPSlevels(atPPSlist,
                          &atPPSlist[pNode->ulNext],
                          iLevel,
                          iRecursionLevel + 1);
    }
    if(pNode->ulPrevious != PPS_NUMBER_INVALID) {
        vComputePPSlevels(atPPSlist,
                          &atPPSlist[pNode->ulPrevious],
                          iLevel,
                          iRecursionLevel + 1);
    }
} /* end of vComputePPSlevels */


bool KBinaryParser::bGetPPS(FILE *pFile,
                            const ULONG *aulRootList, size_t tRootListLen, ppsInfoType *pPPS) {
    ppsEntryType	*atPPSlist;
    ULONG	ulBegin, ulOffset, ulTmp;
    size_t	tNbrOfPPS, tNameSize;
    int	iIndex, iStartBlock, iRootIndex;
    bool	bTypeFind = false;
    UCHAR	aucBytes[PROPERTY_SET_STORAGE_SIZE];

    (void)memset(pPPS, 0, sizeof(*pPPS));

    /* Read and store all the Property Set Storage entries */

    if(tRootListLen > std::numeric_limits<size_t>::max() / BIG_BLOCK_SIZE) {
        return false;
    }
    tNbrOfPPS = tRootListLen * BIG_BLOCK_SIZE / PROPERTY_SET_STORAGE_SIZE;
    if(!bOleAllocationWithinBudget(tNbrOfPPS, sizeof(ppsEntryType))) {
        qWarning() << "Rejecting oversized OLE PPS allocation:"
                   << "ppsCount=" << tNbrOfPPS
                   << "entrySize=" << sizeof(ppsEntryType);
        return false;
    }
    atPPSlist = (ppsEntryType*)xcalloc(tNbrOfPPS, sizeof(ppsEntryType));
    if(atPPSlist == NULL) {
        /*
         * tNbrOfPPS 由 tRootListLen 推导，最终受文件大小约束；但在内存
         * 紧张或字段被恶意拉大时 xcalloc 仍可能返回空。补上判空，避免下面
         * 的循环对 atPPSlist[iIndex] 做空指针访问。
         */
        return false;
    }
    iRootIndex = 0;

    for(iIndex = 0; iIndex < (int)tNbrOfPPS; iIndex++) {
        ulTmp = (ULONG)iIndex * PROPERTY_SET_STORAGE_SIZE;
        iStartBlock = (int)(ulTmp / BIG_BLOCK_SIZE);
        ulOffset = ulTmp % BIG_BLOCK_SIZE;
        ulBegin = (aulRootList[iStartBlock] + 1) * BIG_BLOCK_SIZE +
                  ulOffset;
        if(!bReadBytes(aucBytes, PROPERTY_SET_STORAGE_SIZE,
                       ulBegin, pFile)) {
            atPPSlist = (ppsEntryType*)xfree(atPPSlist);
            return false;
        }
        tNameSize = (size_t)usGetWord(0x40, aucBytes);
        tNameSize = (tNameSize + 1) / 2;
        /*
         * PPS 名称在文件中占固定的 64 字节 UTF-16 区域，转换后的目标是
         * szName[32]。即使文件伪造了更大的名称长度，也不能超出该数组。
         */
        if(tNameSize > sizeof(atPPSlist[iIndex].szName)) {
            atPPSlist = (ppsEntryType*)xfree(atPPSlist);
            return false;
        }
        vName2String(atPPSlist[iIndex].szName, aucBytes, tNameSize);
        atPPSlist[iIndex].ucType = ucGetByte(0x42, aucBytes);
        if(atPPSlist[iIndex].ucType == 5) {
            iRootIndex = iIndex;
        }

        ULONG ulprev = ulGetLong(0x44, aucBytes);
        ULONG ulnxt = ulGetLong(0x48, aucBytes);
        ULONG uldir = ulGetLong(0x4c, aucBytes);
        ULONG ulsb = ulGetLong(0x74, aucBytes);   // 116
        ULONG ulsize = ulGetLong(0x78, aucBytes); // 120
        atPPSlist[iIndex].ulPrevious = ulprev;
        atPPSlist[iIndex].ulNext = ulnxt;
        atPPSlist[iIndex].ulDir = uldir;
        atPPSlist[iIndex].ulSB = ulsb;
        atPPSlist[iIndex].ulSize = ulsize;
        atPPSlist[iIndex].iLevel = INT_MAX;
        if((atPPSlist[iIndex].ulPrevious >= (ULONG)tNbrOfPPS &&
                atPPSlist[iIndex].ulPrevious != PPS_NUMBER_INVALID) ||
                (atPPSlist[iIndex].ulNext >= (ULONG)tNbrOfPPS &&
                 atPPSlist[iIndex].ulNext != PPS_NUMBER_INVALID) ||
                (atPPSlist[iIndex].ulDir >= (ULONG)tNbrOfPPS &&
                 atPPSlist[iIndex].ulDir != PPS_NUMBER_INVALID)) {
            atPPSlist = (ppsEntryType*)xfree(atPPSlist);
            return false;
        }
    }

    /* Add level information to each entry */
    vComputePPSlevels(atPPSlist, &atPPSlist[iRootIndex], 0, 0);

    for(iIndex = 0; iIndex < (int)tNbrOfPPS; iIndex++) {
        if(atPPSlist[iIndex].szName[0] == '\0' ||
                atPPSlist[iIndex].ulSize == 0 ||
                atPPSlist[iIndex].iLevel > 1) { // 过滤掉level大于1（文件里嵌套了子文件）的情况，只处理最外层文件内容的解析
            /* This entry can be ignored */
            continue;
        }
        /*if (m_strFileName.endsWith(".wps") && pPPS->tWordDocument.ulSize == 0 &&
        	STREQ(atPPSlist[iIndex].szName, "Root Entry"))
        {
        	pPPS->tWordDocument.ulSB = 0;//atPPSlist[iIndex].ulSB;
        	pPPS->tWordDocument.ulSize = atPPSlist[iIndex].ulSize;
        	pPPS->type = Word;
        	bTypeFind = true;
        }
        else */if(pPPS->tWordDocument.ulSize == 0 &&
                  STREQ(atPPSlist[iIndex].szName, "WordDocument")) {
            pPPS->tWordDocument.ulSB = atPPSlist[iIndex].ulSB;
            pPPS->tWordDocument.ulSize = atPPSlist[iIndex].ulSize;
            pPPS->type = Word;
            bTypeFind = true;
        } else if(pPPS->tData.ulSize == 0 &&
                  STREQ(atPPSlist[iIndex].szName, "Data")) {
            pPPS->tData.ulSB = atPPSlist[iIndex].ulSB;
            pPPS->tData.ulSize = atPPSlist[iIndex].ulSize;
        } else if(pPPS->t0Table.ulSize == 0 &&
                  STREQ(atPPSlist[iIndex].szName, "0Table")) {
            pPPS->t0Table.ulSB = atPPSlist[iIndex].ulSB;
            pPPS->t0Table.ulSize = atPPSlist[iIndex].ulSize;
        } else if(pPPS->t1Table.ulSize == 0 &&
                  STREQ(atPPSlist[iIndex].szName, "1Table")) {
            pPPS->t1Table.ulSB = atPPSlist[iIndex].ulSB;
            pPPS->t1Table.ulSize = atPPSlist[iIndex].ulSize;
        } else if(pPPS->tSummaryInfo.ulSize == 0 &&
                  STREQ(atPPSlist[iIndex].szName,
                        "\005SummaryInformation")) {
            pPPS->tSummaryInfo.ulSB = atPPSlist[iIndex].ulSB;
            pPPS->tSummaryInfo.ulSize = atPPSlist[iIndex].ulSize;
        } else if(pPPS->tDocSummaryInfo.ulSize == 0 &&
                  STREQ(atPPSlist[iIndex].szName,
                        "\005DocumentSummaryInformation")) {
            pPPS->tDocSummaryInfo.ulSB = atPPSlist[iIndex].ulSB;
            pPPS->tDocSummaryInfo.ulSize = atPPSlist[iIndex].ulSize;
        } else if(pPPS->tWorkBook.ulSize == 0 &&
                  (STREQ(atPPSlist[iIndex].szName, "Book") || STREQ(atPPSlist[iIndex].szName, "Workbook"))) {
            pPPS->tWorkBook.ulSB = atPPSlist[iIndex].ulSB;
            pPPS->tWorkBook.ulSize = atPPSlist[iIndex].ulSize;
            pPPS->type = Excel;
            bTypeFind = true;
        } else if(pPPS->tPPTDocument.ulSize == 0 &&
                  STREQ(atPPSlist[iIndex].szName, "PowerPoint Document")) {
            pPPS->tPPTDocument.ulSB = atPPSlist[iIndex].ulSB;
            pPPS->tPPTDocument.ulSize = atPPSlist[iIndex].ulSize;
            pPPS->type = Ppt;
            bTypeFind = true;
        } else if(pPPS->tCurrentUser.ulSize == 0 &&
                  STREQ(atPPSlist[iIndex].szName, "Current User")) {
            pPPS->tCurrentUser.ulSB = atPPSlist[iIndex].ulSB;
            pPPS->tCurrentUser.ulSize = atPPSlist[iIndex].ulSize;
        }
    }

    /* Free the space for the Property Set Storage entries */
    atPPSlist = (ppsEntryType*)xfree(atPPSlist);

    return bTypeFind;
}/* end of bGetPPS */

int KBinaryParser::readData(rdPara &readParam, uchar *aucBuffer, ulong ulOffset, size_t tToRead) {
    /* Read the headerblock */
    if(!bReadBuffer(readParam.pFile, readParam.ulStBlk,
                    readParam.ulBBd, readParam.tBBdLen, readParam.usBlkSize,
                    aucBuffer, ulOffset, tToRead))
        return -1;
    return 0;
}


bool bCreateSmallBlockList(ULONG ulStartblock, const ULONG *aulBBD, size_t tBBDLen) {
    ULONG	ulTmp;
    size_t	tSize;
    int	iIndex;

    /*
     * 先沿 BBD 链计算小块链表长度。for 的递增表达式会访问 aulBBD[ulTmp]，
     * 所以每一轮都必须先验证 ulTmp，不能等到下一轮再检查。
     */
    for(tSmallBlockListLen = 0, ulTmp = ulStartblock;
            tSmallBlockListLen < tBBDLen && ulTmp != END_OF_CHAIN;
            tSmallBlockListLen++, ulTmp = aulBBD[ulTmp]) {
        if(ulTmp >= (ULONG)tBBDLen) {
            qCritical() << "Fail to find the length of small block list! Start block error!!";
            return false;
        }
    }

    if(tSmallBlockListLen == 0) {
        /* There is no small block list */
        return true;
    }

    /* Create the small block list */
    tSize = tSmallBlockListLen * sizeof(ULONG);
    xfree(aulSmallBlockList);
    aulSmallBlockList = NULL;
    aulSmallBlockList = (ULONG*)xmalloc(tSize);
    if(aulSmallBlockList == NULL) {
        /* 分配失败时直接返回，避免下面对空指针做写入。 */
        return false;
    }
    for(iIndex = 0, ulTmp = ulStartblock;
            iIndex < (int)tBBDLen && ulTmp != END_OF_CHAIN;
            iIndex++, ulTmp = aulBBD[ulTmp]) {
        if(ulTmp >= (ULONG)tBBDLen) {
            return false;
        }
        aulSmallBlockList[iIndex] = ulTmp;
    }
    return true;
} /* end of bCreateSmallBlockList */


static void vGetBbdList(FILE *pFile, int iNbr, ULONG *aulBbdList, ULONG ulOffset) {
    int	iIndex;

    for(iIndex = 0; iIndex < iNbr; iIndex++) {
        aulBbdList[iIndex] = ulReadLong(pFile, ulOffset + 4 * (ULONG)iIndex);
    }
} /* end of vGetBbdList */


static bool bGetBBD(FILE *pFile, const ULONG *aulDepot, size_t tDepotLen,
                    ULONG *aulBBD, size_t tBBDLen) {
    ULONG	ulBegin;
    size_t	tToGo, tDone;
    int	iIndex;

    tToGo = tBBDLen;
    for(iIndex = 0; iIndex < (int)tDepotLen && tToGo != 0; iIndex++) {
        ulBegin = (aulDepot[iIndex] + 1) * BIG_BLOCK_SIZE;
        tDone = tReadBlockIndices(pFile, aulBBD, tToGo, ulBegin);
        if(tDone == 0) {
            return false;
        }
        aulBBD += tDone;
        tToGo -= tDone;
    }
    return tToGo == 0;
} /* end of bGetBBD */

#define REHASH(a) \
	if (sl_minus_1 < (int)sizeof(int) * CHAR_BIT)       \
		hashHaystack -= (a) << sl_minus_1; \
	hashHaystack <<= 1

static inline uint foldCase(const ushort *ch, const ushort *start) {
    uint c = *ch;
    if(QChar(c).isLowSurrogate() && ch > start && QChar(*(ch - 1)).isHighSurrogate())
        c = QChar::surrogateToUcs4(*(ch - 1), c);
    return *ch + qGetProp(c)->caseFoldDiff;
}

static inline uint foldCase(uint ch, uint &last) {
    uint c = ch;
    if(QChar(c).isLowSurrogate() && QChar(last).isHighSurrogate())
        c = QChar::surrogateToUcs4(last, c);
    last = ch;
    return ch + qGetProp(c)->caseFoldDiff;
}

static inline ushort foldCase(ushort ch) {
    return ch + qGetProp(ch)->caseFoldDiff;
}


static int ucstricmp(const ushort *a, const ushort *ae, const ushort *b, const ushort *be) {
    if(a == b)
        return (ae - be);
    if(a == 0)
        return 1;
    if(b == 0)
        return -1;

    const ushort *e = ae;
    if(be - b < ae - a)
        e = a + (be - b);

    uint alast = 0;
    uint blast = 0;
    while(a < e) {
        qDebug() << hex << alast << blast;
        qDebug() << hex << "*a=" << *a << "alast=" << alast << "folded=" << foldCase(*a, alast);
        qDebug() << hex << "*b=" << *b << "blast=" << blast << "folded=" << foldCase(*b, blast);
        int diff = foldCase(*a, alast) - foldCase(*b, blast);
        if((diff))
            return diff;
        ++a;
        ++b;
    }
    if(a == ae) {
        if(b == be)
            return 0;
        return -1;
    }
    return 1;
}

static int ucstrnicmp(const ushort *a, const ushort *b, int l) {
    return ucstricmp(a, a + l, b, b + l);
}

static int ucstrncmp(const QChar *a, const QChar *b, int l) {
    while(l-- && *a == *b)
        a++, b++;
    if(l == -1)
        return 0;
    return a->unicode() - b->unicode();
}

// ── Word 文档文本归一化 ──────────────────────────────────────────────────────
//
// Word97-2003 (.doc) 文本流中混杂着非文本的结构字符（图片占位、对象锚点、
// 域标记等）。这些字符在 MS-DOC 规范中仅当字符属性 fSpec=1 时才具有特殊含义。
//
// 当前实现采用字符值检测策略：遇到这些字符值就当作结构字符处理。
// 理论上存在误判风险（正常文本中极少出现 U+0001 等控制字符），实际可忽略。
//
// 域处理策略：丢弃域代码，保留域结果。这样能保留用户可见文本
// （例如超链接显示文字），同时去掉 HYPERLINK、PAGE 等域指令本身。
//
// TODO: 如果需要 100% 准确，应读取 CHPX（字符属性表）查询每个字符的 fSpec 标志。
// 参考：https://learn.microsoft.com/en-us/openspecs/office_file_formats/ms-doc/

static bool isDroppableUnknownControlCharacter(const QChar &ch)
{
    // 调用方必须先处理当前格式中有语义的控制字符；这里只清理剩余未知 Cc 字符。
    const ushort code = ch.unicode();
    return ch.category() == QChar::Other_Control
            && code != '\t'
            && code != '\r'
            && code != '\n';
}

static void appendWordTableSeparator(QString &out)
{
    if (!out.isEmpty() && !out.back().isSpace()) {
        out.append(QLatin1Char(' '));
    }
}

static void appendOfficeParagraphSeparator(QString &out)
{
    if (out.isEmpty()) {
        return;
    }

    const ushort last = out.back().unicode();
    if (last == '\r' || last == '\n' || last == '\v' || last == '\f') {
        return;
    }

    out.append(QLatin1Char('\r'));
}

static void appendNormalizedOfficeText(QString &out, const QString &text)
{
    for (const QChar ch : text) {
        const ushort code = ch.unicode();
        if (code == '\v' || code == '\f') {
            appendOfficeParagraphSeparator(out);
            continue;
        }
        if (isDroppableUnknownControlCharacter(ch)) {
            continue;
        }

        out.append(ch);
    }
}

void KBinaryParser::normalizeWordText(const QString &text,
                                      WordFieldStateStack &fieldStack,
                                      int &codeDepth,
                                      QString &out)
{
    constexpr uchar kFieldInResult = 0;
    constexpr uchar kFieldInCode = 1;

    for (const QChar ch : text) {
        const ushort code = ch.unicode();

        if (code == kWordCharInlinePicture || code == kWordCharFloatingObject) {
            continue; // Word 专有的对象占位符，用户不可见，直接丢弃
        }
        if (code == kWordCharTableCellMark) {
            if (codeDepth == 0) {
                appendWordTableSeparator(out);
            }
            continue;
        }
        if (code == '\v' || code == '\f' || code == kWordCharColumnBreak) {
            if (codeDepth == 0) {
                appendOfficeParagraphSeparator(out);
            }
            continue;
        }
        if (code == kWordCharFieldBegin) {
            fieldStack.append(kFieldInCode);
            ++codeDepth;
            continue;
        }
        if (code == kWordCharFieldSeparator) {
            if (!fieldStack.isEmpty() && fieldStack.back() == kFieldInCode) {
                fieldStack.back() = kFieldInResult;
                --codeDepth;
            }
            continue;
        }
        if (code == kWordCharFieldEnd) {
            if (!fieldStack.isEmpty()) {
                if (fieldStack.back() == kFieldInCode)
                    --codeDepth;
                fieldStack.removeLast();
            }
            continue;
        }

        if (code == kWordCharNonBreakingHyphen) {
            if (codeDepth == 0) {
                out.append(QLatin1Char('-'));
            }
            continue;
        }
        if (code == kWordCharOptionalHyphen) {
            continue;
        }

        // Word 中有语义的控制字符要在这里先处理，剩余未知控制字符才可清理。
        if (isDroppableUnknownControlCharacter(ch)) {
            continue;
        }

        // 只要没有任何层仍处于 field code 中，就保留字符。
        if (codeDepth == 0)
            out.append(ch);
    }
}

// 判断字符是否为段落分隔符
static bool isParagraphSeparator(QChar ch)
{
    const ushort code = ch.unicode();
    return code == '\r' || code == '\n' || code == '\v' || code == '\f';
}

// 清理只包含空白字符的空段落
// 规则：删除开头和结尾的空段落，保留中间所有内容（包括空段落的分隔符）。
// 最后一个有内容段落之后不保留末尾分隔符。
static QString cleanEmptyParagraphs(const QString &text)
{
    if (text.isEmpty())
        return QString();

    // 找到第一个非空段落的起始位置
    int firstNonEmptyStart = 0;
    while (firstNonEmptyStart < text.size()) {
        int paraEnd = firstNonEmptyStart;
        while (paraEnd < text.size() && !isParagraphSeparator(text[paraEnd]))
            ++paraEnd;

        // 检查段落是否有非空白内容
        bool hasContent = false;
        for (int i = firstNonEmptyStart; i < paraEnd; ++i) {
            if (!text[i].isSpace()) {
                hasContent = true;
                break;
            }
        }

        if (hasContent)
            break;

        firstNonEmptyStart = (paraEnd < text.size()) ? paraEnd + 1 : text.size();
    }

    if (firstNonEmptyStart >= text.size())
        return QString(); // 全是空段落

    // 从后往前找最后一个非空段落的结束位置
    int lastNonEmptyEnd = text.size();
    while (lastNonEmptyEnd > firstNonEmptyStart) {
        // 找到当前段落的起始位置
        int paraStart = lastNonEmptyEnd - 1;
        if (paraStart >= 0 && isParagraphSeparator(text[paraStart]))
            --paraStart;
        while (paraStart > firstNonEmptyStart && !isParagraphSeparator(text[paraStart - 1]))
            --paraStart;

        // 检查段落是否有非空白内容
        bool hasContent = false;
        for (int i = paraStart; i < lastNonEmptyEnd && !isParagraphSeparator(text[i]); ++i) {
            if (!text[i].isSpace()) {
                hasContent = true;
                break;
            }
        }

        if (hasContent) {
            // 找到段落内容的实际结束位置（不含分隔符）
            while (lastNonEmptyEnd > paraStart && isParagraphSeparator(text[lastNonEmptyEnd - 1]))
                --lastNonEmptyEnd;
            break;
        }

        lastNonEmptyEnd = paraStart;
    }

    return text.mid(firstNonEmptyStart, lastNonEmptyEnd - firstNonEmptyStart);
}
inline uint _Ucs2ToUcs4(ushort lead, ushort trail) {
    unsigned int ucs4 = (trail - 0xDC00); //low 10 bit
    ucs4 |= ((lead - 0xD800)) << 10; //high 10 bit
    return ucs4 + 0x10000;
}

bool KBinaryParser::read8DocText(FILE *pFile, const ppsInfoType *pPPS,
                                 const ULONG *aulBBD, size_t tBBDLen,
                                 const ULONG *aulSBD, size_t tSBDLen,
                                 const UCHAR *aucHeader, QString &content) {
    const ULONG	*aulBlockDepot;
    ULONG	ulBeginTextInfo;
    ULONG   ulEncryptInfo;
    size_t	tTextInfoLen, tBlockDepotLen, tBlockSize;

    ulBeginTextInfo = ulGetLong(0x1a2, aucHeader);	/* fcClx */
    tTextInfoLen = (size_t)ulGetLong(0x1a6, aucHeader);	/* lcbClx */
    ulEncryptInfo = ulGetLong(0x0a, aucHeader);
    if(ulEncryptInfo & BIT(8)) {
        qDebug() << "Encrypt file:" << m_strFileName << (size_t)ulEncryptInfo;
        return false;
    }

    if(pPPS->tTable.ulSize == 0)
        return false;

    // lcbClx/fcClx 来自文件头，必须先限制在 Table 流范围内，
    // 否则恶意文件可伪造超大长度触发异常读取或超大内存申请。
    const size_t tTableSize = static_cast<size_t>(pPPS->tTable.ulSize);
    const size_t tTextInfoOffset = static_cast<size_t>(ulBeginTextInfo);
    if(tTextInfoOffset > tTableSize || tTextInfoLen > tTableSize - tTextInfoOffset) {
        qWarning() << "Invalid Word table text info range:" << m_strFileName
                   << "offset=" << tTextInfoOffset
                   << "length=" << tTextInfoLen
                   << "tableSize=" << tTableSize;
        return false;
    }

    if(pPPS->tTable.ulSize < MIN_SIZE_FOR_BBD_USE) {
        /* Use the Small Block Depot */
        aulBlockDepot = aulSBD;
        tBlockDepotLen = tSBDLen;
        tBlockSize = SMALL_BLOCK_SIZE;
    } else {
        /* Use the Big Block Depot */
        aulBlockDepot = aulBBD;
        tBlockDepotLen = tBBDLen;
        tBlockSize = BIG_BLOCK_SIZE;
    }

    // 改为堆分配，避免按外部可控长度在栈上创建 VLA。
    if(tTextInfoLen == 0) {
        return false;
    }

    std::vector<UCHAR> aucBuffer;
    if(tTextInfoLen > aucBuffer.max_size()) {
        qWarning() << "Word CLX buffer length exceeds vector capacity:"
                   << m_strFileName
                   << "length=" << tTextInfoLen
                   << "maxSize=" << aucBuffer.max_size();
        return false;
    }
    try {
        aucBuffer.resize(tTextInfoLen);
    } catch(const std::bad_alloc &) {
        qWarning() << "Failed to allocate Word CLX buffer:"
                   << m_strFileName
                   << "length=" << tTextInfoLen;
        return false;
    }
    if(!bReadBuffer(pFile, pPPS->tTable.ulSB,
                    aulBlockDepot, tBlockDepotLen, tBlockSize,
                    aucBuffer.data(), ulBeginTextInfo, tTextInfoLen))
        return false;

    /*
     * CLX 由若干带类型字节的记录组成：
     *   0x01: Prc，后接 2 字节长度和对应的属性修改数据；
     *   0x02: Pcdt，后接 4 字节长度和 PlcPcd piece table。
     * 下述每次读取多字节字段前都要先校验剩余长度。
     */
    size_t tOff = 0;
    while(tOff < tTextInfoLen) {
        const int iType = (int)ucGetByte(tOff, aucBuffer.data());
        tOff++;
        if(iType == 0) {
            if(!bRangeWithinBuffer(tOff, 1, tTextInfoLen)) {
                qWarning() << "Truncated Word CLX type-0 record:" << m_strFileName;
                return false;
            }
            tOff++;
            continue;
        }
        if(iType == 1) {
            if(!bRangeWithinBuffer(tOff, 2, tTextInfoLen)) {
                qWarning() << "Truncated Word CLX property modifier header:" << m_strFileName;
                return false;
            }
            const size_t tPropertyLength = 2 + (size_t)usGetWord(tOff, aucBuffer.data());
            if(!vAdd2PropModList(aucBuffer.data() + tOff, tTextInfoLen - tOff)) {
                qWarning() << "Invalid Word CLX property modifier length:" << m_strFileName;
                return false;
            }
            tOff += tPropertyLength;
            continue;
        }

        if(iType != 2)
            return false;

        /* Type 2：先读取 piece table 的 4 字节长度字段。 */
        if(!bRangeWithinBuffer(tOff, 4, tTextInfoLen)) {
            qWarning() << "Truncated Word CLX piece table header:" << m_strFileName;
            return false;
        }
        const size_t tPieceTableLength = (size_t)ulGetLong(tOff, aucBuffer.data());
        tOff += 4;
        /*
         * lcb 只表示后续 PlcPcd 的长度，不包含前面的类型字节和 4 字节 lcb。
         * PlcPcd 由 n+1 个 4 字节 CP 和 n 个 8 字节 PCD 组成，因此长度必须
         * 满足 4 * (n + 1) + 8 * n = 12 * n + 4，不能包含不完整的 PCD。
         */
        if(tPieceTableLength < 4 || (tPieceTableLength - 4) % 12 != 0 ||
                !bRangeWithinBuffer(tOff, tPieceTableLength, tTextInfoLen)) {
            qWarning() << "Invalid Word CLX piece table length:" << m_strFileName
                       << "offset=" << tOff
                       << "length=" << tPieceTableLength
                       << "clxLength=" << tTextInfoLen;
            return false;
        }

        /*
         * 此时 tOff 指向 PlcPcd 开头，其布局为：
         *   CP[0] ... CP[n] | PCD[0] ... PCD[n-1]
         *   每个 CP 占 4 字节，每个 PCD 占 8 字节。
         * n 个 piece 需要 n+1 个 CP，因为每个 piece 由相邻的
         * CP[i] 和 CP[i+1] 表示字符起止范围。
         */
        // PlcPcd 末尾位置，仅用于校验后续 CP/PCD 访问没有越界。
        const size_t tPieceTableEnd = tOff + tPieceTableLength;
        // 由总长度 12 * n + 4 反推出 piece 数量 n。
        const size_t tPieces = (tPieceTableLength - 4) / 12;
        // 跳过前面 n+1 个 CP，得到 PCD[0] 的起始位置。
        const size_t tPcdBase = tOff + (tPieces + 1) * 4;
        WordFieldStateStack fieldStack;
        int codeDepth = 0;
        for(size_t tIndex = 0; tIndex < tPieces; tIndex++) {
            // 定位当前 CP[i] 和 PCD[i]；CP[i+1] 位于 tCpOffset + 4。
            const size_t tCpOffset = tOff + tIndex * 4;
            const size_t tPcdOffset = tPcdBase + tIndex * 8;
            // 同时读取 CP[i]/CP[i+1] 需要 8 字节；PCD 中从偏移 2
            // 开始的 6 字节依次包含 4 字节 fc 和 2 字节 prm。
            if(!bRangeWithinBuffer(tCpOffset, 8, tPieceTableEnd) ||
                    !bRangeWithinBuffer(tPcdOffset + 2, 6, tPieceTableEnd)) {
                qWarning() << "Invalid Word CLX piece index:" << m_strFileName;
                return false;
            }

            const ULONG ulCpStart = ulGetLong(tCpOffset, aucBuffer.data());
            const ULONG ulCpEnd = ulGetLong(tCpOffset + 4, aucBuffer.data());
            // 相邻 CP 之差就是当前 piece 中的字符数。
            if(ulCpEnd < ulCpStart) {
                qWarning() << "Descending Word CLX character range:" << m_strFileName;
                return false;
            }

            ULONG ulTextOffset = ulGetLong(tPcdOffset + 2, aucBuffer.data());
            const USHORT usPropMod = usGetWord(tPcdOffset + 6, aucBuffer.data());
            (void)usPropMod;
            size_t tTextLength = (size_t)(ulCpEnd - ulCpStart);
            bool bUsesUnicode;
            // fc 的第 30 位为 0 表示 UTF-16，每个字符占 2 字节；
            // 为 1 表示压缩字符，实际文件偏移需要清除标志位后除以 2。
            if((ulTextOffset & BIT(30)) == 0) {
                bUsesUnicode = true;
                if(tTextLength > std::numeric_limits<size_t>::max() / 2) {
                    return false;
                }
                tTextLength *= 2;
            } else {
                bUsesUnicode = false;
                ulTextOffset &= ~BIT(30);
                ulTextOffset /= 2;
            }

            /*
             * PCD 中的 fc 指向 WordDocument 流内的文本位置。
             * tWordStreamSize 是该流的总字节数，tWordOffset 是解码后的
             * fc 偏移，tTextLength 是当前 piece 实际需要读取的字节数。
             * 前面的 piece table 边界检查只能保证 CP/PCD 位于 Table 流的
             * CLX 缓冲区内，不能保证 PCD 引用的文本位于另一个
             * WordDocument 流内。底层 bReadBytes 只能感知整个物理文件的
             * 末尾，即使越过 WordDocument 流读到其他 OLE 数据也可能成功，
             * 因此这里还必须单独校验文本偏移和长度。
             */
            const size_t tWordStreamSize = (size_t)pPPS->tWordDocument.ulSize;
            const size_t tWordOffset = (size_t)ulTextOffset;
            // 先校验偏移，再用减法校验长度，避免 offset + length 溢出。
            if(tWordOffset > tWordStreamSize ||
                    tTextLength > tWordStreamSize - tWordOffset) {
                qWarning() << "Invalid Word text piece range:" << m_strFileName
                           << "offset=" << tWordOffset
                           << "length=" << tTextLength
                           << "streamSize=" << tWordStreamSize;
                return false;
            }

            size_t tReadOffset = 0;
            ULONG ulFileOffset = (pPPS->tWordDocument.ulSB + 1) * BIG_BLOCK_SIZE + ulTextOffset;
            if(pPPS->tWordDocument.ulSize < MIN_SIZE_FOR_BBD_USE)
                ulFileOffset = ulDepotOffset(pPPS->tWordDocument.ulSB, SMALL_BLOCK_SIZE) + ulTextOffset;
            while(tReadOffset < tTextLength) {
                const size_t tAllocSize = min(tTextLength - tReadOffset,
                                              (size_t)MAX_BUFF_SIZE);

                UCHAR *ptaucBytes = (UCHAR*)xmalloc(tAllocSize);
                if(!ptaucBytes)
                    return false;
                if(!bReadBytes(ptaucBytes, tAllocSize, ulFileOffset, pFile)) {
                    ptaucBytes = (UCHAR*)xfree(ptaucBytes);
                    return false;
                }

                ulFileOffset += tAllocSize;
                tReadOffset += tAllocSize;

                if(bUsesUnicode) {
                    ushort* usAucData = (ushort*)ptaucBytes;
                    QString rawText = QString::fromUtf16(usAucData, tAllocSize/2);
                    normalizeWordText(rawText, fieldStack, codeDepth, content);
                    usAucData = (ushort*)xfree((void*)usAucData);
                    if(content.length() >= 682666) //20480000/3
                        break;
                } else {
                    //need more format document
                    ptaucBytes = (UCHAR*)xfree((void*)ptaucBytes);
                }
            }
        }
        break;
    }

    // 清理只包含空白字符的段落（例如：只有图片的段落）
    content = cleanEmptyParagraphs(content);

    return true;
}/* end of bGet8DocumentText */

bool KBinaryParser:: readSSTRecord(readDataParam &rdParam, ppsInfoType PPS_info, ulong &ulOff, ushort usPartLen, QString &content) {
    static constexpr quint64 kMaxBiffRecordPayload = 8224;

    // Workbook 流内使用绝对逻辑偏移。这里不修改 ulOff，旧式
    // InitDocOle() 的 Workbook 记录扫描在 SST/CONTINUE 消费完成后
    // 会立即停止，因此不必再向调用方回写“下一记录偏移”。
    const quint64 workbookSize =
        static_cast<quint64>(PPS_info.tWorkBook.ulSize);

    quint64 cursor = static_cast<quint64>(ulOff) + 8;
    quint64 recordEnd = static_cast<quint64>(ulOff) + usPartLen;

    if (usPartLen < 8 ||
        static_cast<quint64>(usPartLen) > kMaxBiffRecordPayload ||
        static_cast<quint64>(ulOff) > workbookSize ||
        usPartLen > workbookSize - static_cast<quint64>(ulOff)) {
        return false;
    }

    uchar sizeData[8];
    if (readData(rdParam, sizeData, ulOff, sizeof(sizeData)) != 0)
        return false;

    const quint64 uniqueStringCount = ulGetLong(4, sizeData);

    // 切换到下一条 CONTINUE，仅消费记录头。若 CONTINUE 从下一完整字符串
    // 开始，其负载首字节就是 cch，不能当作 fHighByte 消费。
    auto enterContinueRecord = [&]() -> bool {
        if (cursor != recordEnd ||
            recordEnd > workbookSize ||
            4 > workbookSize - recordEnd ||
            recordEnd >
                static_cast<quint64>(
                    std::numeric_limits<ulong>::max())) {
            return false;
        }

        uchar header[4];
        if (readData(rdParam,
                     header,
                     static_cast<ulong>(recordEnd),
                     sizeof(header)) != 0) {
            return false;
        }

        if (usGetWord(0, header) != 0x003c)
            return false;

        // 合法 BIFF CONTINUE 必然带负载。0 长度 CONTINUE 只可能来自
        // 构造文件：它让每次调用仅推进 4 字节，虽然受 workbookSize
        // 约束不会真的死循环，但会造成无意义的重复读取，直接拒绝。
        const quint64 payloadLength = usGetWord(2, header);
        if (payloadLength == 0 ||
            payloadLength > kMaxBiffRecordPayload) {
            return false;
        }

        cursor = recordEnd + 4;

        if (cursor > workbookSize ||
            payloadLength > workbookSize - cursor) {
            return false;
        }

        recordEnd = cursor + payloadLength;

        return cursor < recordEnd;
    };

    // 同一个 XLUnicodeRichExtendedString 的 variable fields 跨 CONTINUE 时，
    // 续段首字节是 fHighByte；字符数组和尾字段都必须消费该字节。
    auto enterStringContinue = [&](bool &compressed) -> bool {
        if (!enterContinueRecord())
            return false;

        if (cursor > static_cast<quint64>(std::numeric_limits<ulong>::max())) {
            return false;
        }

        uchar continuationOption;
        if (readData(rdParam,
                     &continuationOption,
                     static_cast<ulong>(cursor),
                     1) != 0) {
            return false;
        }

        // fHighByte 在续段中只能取 0 或 1；不能把其他 grbit 位
        // 当作编码标志容忍，否则会接受结构非法的 CONTINUE。
        if (continuationOption != 0 && continuationOption != 1)
            return false;

        compressed = (continuationOption & 0x01) == 0;
        ++cursor;

        return true;
    };

    // MS-XLS 要求 cch、grbit、cRun 与 cbExtRst 这些 non-variable fields
    // 不能跨记录边界。只允许随后的字符数组和尾字段续接到 CONTINUE。
    auto readHeaderField = [&](uchar *dest, size_t length) -> bool {
        if (cursor > recordEnd || length > recordEnd - cursor ||
            cursor > static_cast<quint64>(std::numeric_limits<ulong>::max()))
            return false;
        if (readData(rdParam, dest, static_cast<ulong>(cursor), length) != 0)
            return false;
        cursor += length;
        return true;
    };

    bool extractionTruncated = false;

    for (quint64 stringIndex = 0;
         stringIndex < uniqueStringCount;
         ++stringIndex) {
        // 上一字符串可能恰好结束于记录边界。此时 CONTINUE 从下一字符串
        // 的 non-variable fields 开始，不包含 fHighByte。
        if (cursor == recordEnd && !enterContinueRecord())
            return false;

        uchar stringHeader[3];
        if (!readHeaderField(stringHeader, sizeof(stringHeader)))
            return false;

        const ushort characterCount =
            usGetWord(0, stringHeader);
        const uchar option = stringHeader[2];
        // fHighByte==0 表示压缩存储；跨 CONTINUE 时该标志会重新给出，
        // 所以 compressed 是可变的。
        bool compressed = (option & 0x01) == 0;

        SstStringMetadata metadata;
        const bool hasRichRuns = (option & 0x08) != 0;
        const bool hasExtendedData = (option & 0x04) != 0;

        if (hasRichRuns) {
            uchar richRunCount[2];
            if (!readHeaderField(richRunCount, sizeof(richRunCount)))
                return false;
            metadata.richRunCount = usGetWord(0, richRunCount);
        }

        if (hasExtendedData) {
            uchar extendedLength[4];
            if (!readHeaderField(extendedLength, sizeof(extendedLength))) {
                return false;
            }
            metadata.extendedDataByteCount = ulGetLong(0, extendedLength);
        }

        // 统一归一化到 UTF-16，后续追加文本只有一个分支。
        const size_t allocationSize =
            static_cast<size_t>(characterCount) *
            sizeof(ushort);

        ushort *characters = nullptr;
        if (allocationSize > 0) {
            characters = static_cast<ushort *>(
                xmalloc(allocationSize));
            if (characters == nullptr)
                return false;
        }

        // BIFF 记录负载上限为 8224 字节；使用同尺寸栈缓冲区承接单次
        // readData()，避免原来 1 MiB 的栈数组。
        uchar chunk[8224];
        quint64 charactersRead = 0;

        while (charactersRead < characterCount) {
            const quint64 bytesPerCharacter =
                compressed ? 1u : 2u;
            const quint64 availableBytes =
                recordEnd - cursor;
            const quint64 availableCharacters =
                availableBytes / bytesPerCharacter;
            const quint64 maxChunkCharacters =
                static_cast<quint64>(sizeof(chunk)) /
                bytesPerCharacter;
            const quint64 chunkCharacters =
                qMin<quint64>(
                    characterCount - charactersRead,
                    qMin(availableCharacters,
                         maxChunkCharacters));

            if (chunkCharacters == 0) {
                if (!enterStringContinue(compressed)) {
                    characters =
                        static_cast<ushort *>(xfree(characters));
                    return false;
                }
                continue;
            }

            const size_t chunkBytes =
                static_cast<size_t>(
                    chunkCharacters * bytesPerCharacter);

            if (readData(rdParam,
                         chunk,
                         static_cast<ulong>(cursor),
                         chunkBytes) != 0) {
                characters =
                    static_cast<ushort *>(xfree(characters));
                return false;
            }

            for (quint64 i = 0; i < chunkCharacters; ++i) {
                if (compressed) {
                    characters[charactersRead + i] =
                        chunk[i];
                } else {
                    characters[charactersRead + i] =
                        static_cast<ushort>(
                            chunk[2 * i] |
                            (static_cast<ushort>(
                                 chunk[2 * i + 1]) << 8));
                }
            }

            cursor += chunkBytes;
            charactersRead += chunkCharacters;

            if (charactersRead < characterCount &&
                cursor != recordEnd) {
                characters =
                    static_cast<ushort *>(xfree(characters));
                return false;
            }
        }

        const QString stringText =
            characterCount == 0
                ? QString()
                : QString::fromUtf16(
                      characters,
                      static_cast<int>(characterCount));

        characters =
            static_cast<ushort *>(xfree(characters));

        // fHighByte 只决定存储宽度（压缩 1 字节/字符，未压缩 2 字节），
        // 上面的读取循环已把两者统一解码为 UTF-16，因此这里不再区分。
        if (!content.isEmpty())
            content.append(QLatin1Char(' '));

        appendNormalizedOfficeText(content, stringText);

        quint64 trailingBytes =
            static_cast<quint64>(metadata.richRunCount) * 4u +
            static_cast<quint64>(metadata.extendedDataByteCount);

        while (trailingBytes > 0) {
            const quint64 bytesHere =
                qMin(trailingBytes, recordEnd - cursor);

            cursor += bytesHere;
            trailingBytes -= bytesHere;

            bool ignoredCompressed = false;
            if (trailingBytes > 0 &&
                !enterStringContinue(ignoredCompressed)) {
                return false;
            }
        }

        // 达到提取上限属于有意截断，不是损坏的 SST。
        if (content.length() >= 682666) { // 20480000/3
            extractionTruncated = stringIndex + 1 < uniqueStringCount;
            break;
        }
    }

    // 正常完成时，SST 最后一条记录的负载应当恰好由已声明的字符串耗尽。
    // 达到提取上限后的主动截断不要求继续扫描剩余负载。
    return extractionTruncated || cursor == recordEnd;
}

ULONG KBinaryParser::readPPtRecord(FILE* pFile, ppsInfoType* PPS_info,
                                   ULONG* aulBBD, size_t tBBDLen,
                                   ULONG ulPos, QString &content,
                                   size_t tContainerEnd,
                                   size_t recursionDepth) {
    // 参数来自上层 OLE 解析结果；空指针或递归层数异常时不能继续读取记录。
    if(pFile == NULL || PPS_info == NULL || aulBBD == NULL ||
            recursionDepth > MAX_PPT_RECORD_RECURSION_DEPTH) {
        return PPT_RECORD_ERROR;
    }

    // 一条 PPT 记录至少要完整容纳 8 字节记录头，避免在流末尾读取残缺头部。
    const size_t tStreamSize = static_cast<size_t>(PPS_info->tPPTDocument.ulSize);
    const size_t tRecordOffset = static_cast<size_t>(ulPos);
    if(tContainerEnd > tStreamSize ||
            !bRangeWithinBuffer(tRecordOffset, PPT_RECORD_HEADER, tContainerEnd)) {
        return PPT_RECORD_ERROR;
    }

    UCHAR	aucHeader[PPT_RECORD_HEADER];
    ULONG	ulOff = ulPos;
    /* Read the headerblock */
    if(!bReadBuffer(pFile, PPS_info->tPPTDocument.ulSB,
                    aulBBD, tBBDLen, BIG_BLOCK_SIZE,
                    aucHeader, ulOff, PPT_RECORD_HEADER))
        return PPT_RECORD_ERROR;

    ulOff += PPT_RECORD_HEADER;
    USHORT usVersion = usGetWord(0x00, aucHeader);
    USHORT usType = usGetWord(0x02, aucHeader);
    ULONG ulLen = ulGetLong(0x04, aucHeader);
    // ulLen 来自文件记录头，记录体必须完全位于 PowerPoint Document 流内。
    const size_t tPayloadOffset = static_cast<size_t>(ulOff);
    const size_t tPayloadLength = static_cast<size_t>(ulLen);
    if(!bRangeWithinBuffer(tPayloadOffset, tPayloadLength, tContainerEnd)) {
        return PPT_RECORD_ERROR;
    }
    const size_t tPayloadEnd = tPayloadOffset + tPayloadLength;

    USHORT usVer = usVersion & 0xF;
    if(usVer == 0xF) {
        // 版本低 4 位为 0xF 表示容器记录，需要递归解析其记录体中的子记录。
        if(recursionDepth == MAX_PPT_RECORD_RECURSION_DEPTH) {
            return PPT_RECORD_ERROR;
        }

        const bool wasInSlideMaster = m_pptEnterSlideMaster;
        if (usType == PPT_SLIDE_MASTER) {
            m_pptEnterSlideMaster = true;
        }

        while(static_cast<size_t>(ulOff) < tPayloadEnd) {
            const ULONG ulNext = readPPtRecord(pFile, PPS_info, aulBBD, tBBDLen,
                                               ulOff, content,
                                               tPayloadEnd,
                                               recursionDepth + 1);
            // 子记录必须向前推进且不能越过当前容器，否则会死循环或串到相邻记录。
            if(ulNext == PPT_RECORD_ERROR || ulNext <= ulOff ||
                    static_cast<size_t>(ulNext) > tPayloadEnd) {
                m_pptEnterSlideMaster = wasInSlideMaster;
                return PPT_RECORD_ERROR;
            }
            ulOff = ulNext;
        }
        m_pptEnterSlideMaster = wasInSlideMaster;
    } else {
        if((usType == PPT_TEXT_BYTES_ATOM || usType == PPT_TEXT_CHARS_ATOM) && !m_pptEnterSlideMaster) {
            if(ulLen == 0) {
                return static_cast<ULONG>(tPayloadEnd);
            }
            UCHAR* chData = (UCHAR*)xmalloc(tPayloadLength);
            if(chData == NULL) {
                /* ulLen 来自文件且可被恶意拉大，分配失败时直接放弃该记录。 */
                return PPT_RECORD_ERROR;
            }
            if(!bReadBuffer(pFile, PPS_info->tPPTDocument.ulSB,
                            aulBBD, tBBDLen, BIG_BLOCK_SIZE,
                            chData, ulOff, tPayloadLength)) {
                chData = (UCHAR*)xfree(chData);
                return PPT_RECORD_ERROR;
            }
            if(usType == PPT_TEXT_CHARS_ATOM) {
                appendNormalizedOfficeText(content,
                    QString::fromUtf16(reinterpret_cast<const ushort*>(chData),
                                       tPayloadLength / 2));
            } else {
                appendNormalizedOfficeText(content,
                    QString::fromLatin1(reinterpret_cast<const char*>(chData),
                                        static_cast<int>(min(tPayloadLength,
                                            static_cast<size_t>(std::numeric_limits<int>::max())))));
            }
            chData = (UCHAR*)xfree(chData);
        }
        ulOff = static_cast<ULONG>(tPayloadEnd);
        if(content.length() >= 682666) //20480000/3
            return ulOff;
    }
    return ulOff;
}

int KBinaryParser::InitDocOle(FILE* pFile, long lFilesize, QString &content) {
    ppsInfoType	PPS_info;
    ULONG	*aulBBD, *aulSBD;
    ULONG	*aulRootList, *aulBbdList, *aulSbdList;
    ULONG	ulBdbListStart, ulAdditionalBBDlist;
    ULONG	ulRootStartblock, ulSbdStartblock, ulSBLstartblock;
    ULONG	ulStart, ulTmp;
    long	lMaxBlock;
    size_t	tBBDLen, tSBDLen, tNumBbdBlocks, tRootListLen;
    int	 iIndex, iToGo;
    bool	bSuccess;
    USHORT	usIdent, usDocStatus;

    lMaxBlock = lFilesize / BIG_BLOCK_SIZE - 2;
    if(lMaxBlock < 1)
        return -1;

    tBBDLen = (size_t)(lMaxBlock + 1);
    tNumBbdBlocks = (size_t)ulReadLong(pFile, 0x2c);
    ulRootStartblock = ulReadLong(pFile, 0x30);
    ulSbdStartblock = ulReadLong(pFile, 0x3c);
    ulAdditionalBBDlist = ulReadLong(pFile, 0x44);
    /*
     * 这些计数和块索引都直接来自 OLE 文件头，可被恶意构造。
     * tBBDLen 由真实文件大小推导，不做人为上限（否则会误伤合法大文档）；
     * 这里只校验头部字段与文件实际容量是否自洽：BBD 块数不能超过文件中
     * 的大块总数，根目录/附加 BBD 链的起始块号必须落在大块范围内。
     */
    if(tNumBbdBlocks > tBBDLen ||
            ulRootStartblock == ULONG_MAX ||
            ulRootStartblock == END_OF_CHAIN ||
            ulRootStartblock >= (ULONG)tBBDLen ||
            (ulAdditionalBBDlist != END_OF_CHAIN &&
             (ulAdditionalBBDlist == ULONG_MAX ||
              ulAdditionalBBDlist >= (ULONG)tBBDLen))) {
        qWarning() << "Rejecting inconsistent OLE header:" << m_strFileName
                   << "bbdLen=" << tBBDLen
                   << "bbdBlocks=" << tNumBbdBlocks
                   << "rootStart=" << ulRootStartblock
                   << "additionalBbd=" << ulAdditionalBBDlist;
        return -1;
    }
    const size_t tFatEntriesPerBlock = BIG_BLOCK_SIZE / 4;
    if(tNumBbdBlocks > std::numeric_limits<size_t>::max() / tFatEntriesPerBlock ||
            tBBDLen > tNumBbdBlocks * tFatEntriesPerBlock) {
        qWarning() << "Rejecting inconsistent OLE FAT:" << m_strFileName
                   << "bbdLen=" << tBBDLen
                   << "bbdBlocks=" << tNumBbdBlocks
                   << "fatEntriesPerBlock=" << tFatEntriesPerBlock;
        return -1;
    }
    ulSBLstartblock = ulReadLong(pFile,
                                 (ulRootStartblock + 1) * BIG_BLOCK_SIZE + 0x74);
    tSBDLen = (size_t)(ulReadLong(pFile,
                                  (ulRootStartblock + 1) * BIG_BLOCK_SIZE + 0x78) /
                       SMALL_BLOCK_SIZE);
    /*
     * small-block depot 的条目数受文件物理容量约束：每个 small block 占
     * SMALL_BLOCK_SIZE 字节，数量不可能超过 文件大小 / SMALL_BLOCK_SIZE。
     */
    if(tSBDLen > (size_t)(lFilesize / SMALL_BLOCK_SIZE)) {
        qWarning() << "Rejecting inconsistent OLE small block depot:" << m_strFileName
                   << "sbdLen=" << tSBDLen
                   << "fileSize=" << lFilesize;
        return -1;
    }
    if(!bOleAllocationWithinBudget(tNumBbdBlocks, sizeof(ULONG)) ||
            !bOleAllocationWithinBudget(tBBDLen, sizeof(ULONG)) ||
            !bOleAllocationWithinBudget(tSBDLen, sizeof(ULONG))) {
        qWarning() << "Rejecting oversized OLE depot allocation:" << m_strFileName
                   << "bbdLen=" << tBBDLen
                   << "bbdBlocks=" << tNumBbdBlocks
                   << "sbdLen=" << tSBDLen
                   << "entrySize=" << sizeof(ULONG)
                   << "budget=" << MAX_OLE_DEPOT_ALLOCATION_BYTES;
        return -1;
    }

    /* All to be xcalloc-ed pointers to NULL */
    aulRootList = NULL;
    aulSbdList = NULL;
    aulBbdList = NULL;
    aulSBD = NULL;
    aulBBD = NULL;

    aulBbdList = (ULONG*)xcalloc(tNumBbdBlocks, sizeof(ULONG));
    aulBBD = (ULONG*)xcalloc(tBBDLen, sizeof(ULONG));
    if(aulBbdList == NULL || aulBBD == NULL) {
        xfree(aulBbdList);
        xfree(aulBBD);
        return -1;
    }
    iToGo = (int)tNumBbdBlocks;
    vGetBbdList(pFile, min(iToGo, 109),  aulBbdList, 0x4c);
    ulStart = 109;
    iToGo -= 109;
    while(ulAdditionalBBDlist != END_OF_CHAIN && iToGo > 0) {
        ulBdbListStart = (ulAdditionalBBDlist + 1) * BIG_BLOCK_SIZE;
        vGetBbdList(pFile, min(iToGo, 127),
                    aulBbdList + ulStart, ulBdbListStart);
        ulAdditionalBBDlist = ulReadLong(pFile,
                                         ulBdbListStart + 4 * 127);
        ulStart += 127;
        iToGo -= 127;
    }

    if(!bGetBBD(pFile, aulBbdList, tNumBbdBlocks, aulBBD, tBBDLen)) {
        xfree(aulBbdList);
        xfree(aulBBD);
        return -1;
    }

    aulBbdList = (ULONG*)xfree(aulBbdList);
    /* Small Block Depot */
    aulSbdList = (unsigned long*)xcalloc(tBBDLen, sizeof(ULONG));
    aulSBD = (unsigned long*)xcalloc(tSBDLen, sizeof(ULONG));
    if(aulSbdList == NULL || aulSBD == NULL) {
        aulSbdList = (ULONG*)xfree(aulSbdList);
        aulSBD = (ULONG*)xfree(aulSBD);
        aulBBD = (ULONG*)xfree(aulBBD);
        return -1;
    }

    for(iIndex = 0, ulTmp = ulSbdStartblock;
            iIndex < (int)tBBDLen && ulTmp != END_OF_CHAIN;
            iIndex++, ulTmp = aulBBD[ulTmp]) {
        if(ulTmp >= (ULONG)tBBDLen) {
            qWarning("The Big Block Depot is damaged");
            aulSBD = (ULONG*)xfree(aulSBD);
            aulBBD = (ULONG*)xfree(aulBBD);
            return -1;
        }

        aulSbdList[iIndex] = ulTmp;
    }

    if(!bGetSBD(pFile, aulSbdList, tBBDLen, aulSBD, tSBDLen)) {
        aulSBD = (ULONG*)xfree(aulSBD);
        aulBBD = (ULONG*)xfree(aulBBD);
        return -1;
    }


    aulSbdList = (ULONG*)xfree(aulSbdList);
    /* Root list */
    for(tRootListLen = 0, ulTmp = ulRootStartblock;
            tRootListLen < tBBDLen && ulTmp != END_OF_CHAIN;
            tRootListLen++, ulTmp = aulBBD[ulTmp]) {
        if(ulTmp >= (ULONG)tBBDLen) {
            aulSBD = (ULONG*)xfree(aulSBD);
            aulBBD = (ULONG*)xfree(aulBBD);
            return -1;
        }

    }
    if(tRootListLen == 0) {
        aulSBD = (ULONG*)xfree(aulSBD);
        aulBBD = (ULONG*)xfree(aulBBD);
        return -1;
    }

    aulRootList = (ULONG*)xcalloc(tRootListLen, sizeof(ULONG));
    if(aulRootList == NULL) {
        aulSBD = (ULONG*)xfree(aulSBD);
        aulBBD = (ULONG*)xfree(aulBBD);
        return -1;
    }
    for(iIndex = 0, ulTmp = ulRootStartblock;
            iIndex < (int)tBBDLen && ulTmp != END_OF_CHAIN;
            iIndex++, ulTmp = aulBBD[ulTmp]) {
        if(ulTmp >= (ULONG)tBBDLen) {
            aulSBD = (ULONG*)xfree(aulSBD);
            aulBBD = (ULONG*)xfree(aulBBD);
            return -1;
        }

        aulRootList[iIndex] = ulTmp;
    }
    bSuccess = bGetPPS(pFile, aulRootList, tRootListLen, &PPS_info);
    aulRootList = (ULONG*)xfree(aulRootList);
    if(!bSuccess) {
        aulSBD = (ULONG*)xfree(aulSBD);
        aulBBD = (ULONG*)xfree(aulBBD);
        return -1;
    }

    rdPara readParam;
    readParam.pFile = pFile;
    readParam.tBBdLen = tBBDLen;
    readParam.ulBBd = aulBBD;
    readParam.usBlkSize = BIG_BLOCK_SIZE;
    if(PPS_info.type == Word) {
        readParam.ulStBlk = PPS_info.tWordDocument.ulSB;
        UCHAR	aucHeader[HEADER_SIZE];
        /* Small block list */
        if(!bCreateSmallBlockList(ulSBLstartblock, aulBBD, tBBDLen)) {
            aulSBD = (ULONG*)xfree(aulSBD);
            readParam.ulBBd = (ULONG*)xfree(readParam.ulBBd);
            return -1;
        }

        if(PPS_info.tWordDocument.ulSize < MIN_SIZE_FOR_BBD_USE) {
            readParam.ulBBd = aulSBD;
            readParam.tBBdLen = tSBDLen;
            readParam.usBlkSize = SMALL_BLOCK_SIZE;
        }

        if(readData(readParam, aucHeader, 0, HEADER_SIZE) != 0) {
            aulSBD = (ULONG*)xfree(aulSBD);
            aulBBD = (ULONG*)xfree(aulBBD);
            return -1;
        }

        usIdent = usGetWord(0x00, aucHeader);

        if(usIdent != 0x8098 &&	/* Word 7 for oriental languages */
                usIdent != 0x8099 &&	/* Word 7 for oriental languages */
                usIdent != 0xa5dc &&	/* Word 6 & 7 */
                usIdent != 0xa5ec &&	/* Word 7 & 97 & 98 */
                usIdent != 0xa697 &&	/* Word 7 for oriental languages */
                usIdent != 0xa699) {    /* Word 7 for oriental languages */
            aulSBD = (ULONG*)xfree(aulSBD);
            aulBBD = (ULONG*)xfree(aulBBD);
            return -1;
        }

        /* Get the status flags from the header */
        usDocStatus = usGetWord(0x0a, aucHeader);
        if(usDocStatus & BIT(9))
            PPS_info.tTable = PPS_info.t1Table;
        else
            PPS_info.tTable = PPS_info.t0Table;

        if(!read8DocText(pFile,
                        &PPS_info,
                        aulBBD, tBBDLen, aulSBD, tSBDLen,
                        aucHeader, content)) {
            aulSBD = (ULONG*)xfree(aulSBD);
            aulBBD = (ULONG*)xfree(aulBBD);
            return -1;
        }
    } else if(PPS_info.type == Excel) {
        readParam.ulStBlk = PPS_info.tWorkBook.ulSB;
        UCHAR aucHeader[8];
        ulong ulOff = 0;
        if(readData(readParam, aucHeader, 0, 8) != 0) {
            aulSBD = (ULONG*)xfree(aulSBD);
            aulBBD = (ULONG*)xfree(aulBBD);
            return -1;
        }
        ulOff += 4;
        USHORT usType = usGetWord(0x00, aucHeader);

        while(ulOff < PPS_info.tWorkBook.ulSize) {
            USHORT usLen = usGetWord(0x02, aucHeader);
            ulOff += usLen;
            if(readData(readParam, aucHeader, ulOff, 4) != 0)
                break;
            ulOff += 4;
            usType = usGetWord(0x00, aucHeader);
            ushort usPartLen = usGetWord(0x02, aucHeader);
            if(usType == 0x00FC) {
                const bool sstParsed =
                    readSSTRecord(readParam, PPS_info, ulOff, usPartLen, content);
                if (!sstParsed)
                    qWarning() << "Invalid SST record stream:" << m_strFileName;
                break;
            }
        }
    } else if(PPS_info.type == Ppt) {
        ULONG ulOff = 0;
        while(ulOff < PPS_info.tPPTDocument.ulSize) {
            const ULONG ulNext = readPPtRecord(pFile, &PPS_info, aulBBD,
                                               tBBDLen, ulOff, content,
                                               PPS_info.tPPTDocument.ulSize);
            if(ulNext == PPT_RECORD_ERROR || ulNext <= ulOff) {
                qWarning() << "Invalid PowerPoint record stream:" << m_strFileName;
                aulSBD = (ULONG*)xfree(aulSBD);
                aulBBD = (ULONG*)xfree(aulBBD);
                return -1;
            }
            ulOff = ulNext;
        }
    } else {
        qWarning() << "Unsupport doc type:" << m_strFileName;
    }
    aulSBD = (ULONG*)xfree(aulSBD);
    aulBBD = (ULONG*)xfree(aulBBD);
    return 0;
}

long lGetFilesize(const char *szFilename) {
    struct stat	tBuffer;
    if(stat(szFilename, &tBuffer) != 0) {
        //qWarning() << "Get Filesize error";
        return -1;
    }
    if(!S_ISREG(tBuffer.st_mode)) {
        //qWarning() << "It's not a regular file";
        return -1;
    }
    return (long)tBuffer.st_size;
}

KBinaryParser::KBinaryParser(QObject *parent)
    : QObject(parent)
    , m_strFileName("") {
}

KBinaryParser::~KBinaryParser()
{
    xfree(aulSmallBlockList);
    aulSmallBlockList = NULL;
}

bool KBinaryParser::RunParser(QString strFile, QString &content) {
    using FilePtr = std::unique_ptr<FILE, int (*)(FILE *)>;
    FilePtr pFile(fopen(strFile.toLocal8Bit().data(), "rb"), &fclose);
    if(!pFile) {
        return false;
    }

    try {
        m_strFileName = strFile;
        const long lFileSize = lGetFilesize(strFile.toLocal8Bit().data());
        if(lFileSize < 0) {
            qWarning() << "ERROR SIZE";
            return false;
        }
        // If InitDocOle failed, -1 will be returned.
        if(InitDocOle(pFile.get(), lFileSize, content)) {
            qWarning() << "InitDocOle failed!" << strFile;
            return false;
        }
    } catch(const std::exception &error) {
        qWarning() << "Office parser exception:" << strFile << error.what();
        return false;
    } catch(...) {
        qWarning() << "Unknown Office parser exception:" << strFile;
        return false;
    }

    return true;
}
